from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np

def construct_indenyl():
 m=Chem.RWMol(); names={}
 for n in ['b0','b1','b2','b3','b4','b5','p2','p3','p4','ph0','ph1','ph2','ph3','ph4','ph5','me']:
  a=Chem.Atom('C');
  if n in ['b0','b1','b2','b3','b4','b5','p2','p3','p4','ph0','ph1','ph2','ph3','ph4','ph5']:
   a.SetIsAromatic(True)
  if n=='p2':a.SetFormalCharge(-1);a.SetNumExplicitHs(1);a.SetNoImplicit(True)
  names[n]=m.AddAtom(a)
 def bond(a,b,typ=Chem.BondType.AROMATIC):m.AddBond(names[a],names[b],typ)
 for ring in [['b0','b1','b2','b3','b4','b5'],['b4','b3','p2','p3','p4'],['ph0','ph1','ph2','ph3','ph4','ph5']]:
  for a,b in zip(ring,ring[1:]+ring[:1]):
   if m.GetBondBetweenAtoms(names[a],names[b]) is None:bond(a,b)
 bond('p4','ph0',Chem.BondType.SINGLE);bond('p3','me',Chem.BondType.SINGLE)
 mol=m.GetMol();Chem.SanitizeMol(mol)
 return mol,names

def construct_tetralin(chir=Chem.ChiralType.CHI_TETRAHEDRAL_CCW):
 m=Chem.RWMol(); names={}
 for n,e in [('a','C'),('b','C'),('c','C'),('d','C'),('e','C'),('f','C'),('s1','C'),('st','C'),('s3','C'),('s4','C'),('ox','O'),('si','Si'),('si1','C'),('si2','C'),('si3','C'),('n','N'),('co','C'),('oo','O'),('oe','O'),('ch2','C'),('ccl','C'),('cl1','Cl'),('cl2','Cl'),('cl3','Cl')]:
  a0=Chem.Atom(e)
  if n in ['a','b','c','d','e','f']:a0.SetIsAromatic(True)
  if n=='st':a0.SetChiralTag(chir)
  names[n]=m.AddAtom(a0)
 def bond(a,b,t=Chem.BondType.SINGLE):m.AddBond(names[a],names[b],t)
 for x,y in zip(['a','b','c','d','e','f'],['b','c','d','e','f','a']):bond(x,y,Chem.BondType.AROMATIC)
 for x,y in zip(['a','s1','st','s3','s4'],['s1','st','s3','s4','f']):bond(x,y)
 for x,y in [('d','ox'),('ox','si'),('si','si1'),('si','si2'),('si','si3'),('st','n'),('n','co'),('co','oo'),('co','oe'),('oe','ch2'),('ch2','ccl'),('ccl','cl1'),('ccl','cl2'),('ccl','cl3')]:bond(x,y)
 m.GetBondBetweenAtoms(names['co'],names['oo']).SetBondType(Chem.BondType.DOUBLE)
 mol=m.GetMol();Chem.SanitizeMol(mol)
 return mol,names

def prepare(m,seed=14):
 m=Chem.AddHs(m);r=AllChem.EmbedMolecule(m,randomSeed=seed,maxAttempts=1000)
 if r<0:raise RuntimeError('embedding failed')
 prop=AllChem.MMFFGetMoleculeProperties(m)
 if prop:AllChem.MMFFOptimizeMolecule(m,maxIters=400)
 return m

def get_xyz(m):return np.array(m.GetConformer().GetPositions())

def align_from_anchors(m,names,targets):
 xyz=get_xyz(m);ii=[names[n] for n in targets];src=xyz[ii];tar=np.array(list(targets.values()),float)
 src_c=src.mean(axis=0);tar_c=tar.mean(axis=0)
 u,s,vt=np.linalg.svd((src-src_c).T@(tar-tar_c))
 diag=np.diag([1,1,np.linalg.det(u@vt)]);rotation=u@diag@vt
 return (xyz-src_c)@rotation+tar_c

