target={'n':(1.99,-0.53,0.0),'st':(2.60,-1.77,-0.19),'s1':(1.32,-2.22,-0.21),'s3':(3.93,-2.13,-0.16),'s4':(3.60,-3.53,-0.20),'a':(0.58,-3.34,-0.19),'f':(1.67,-4.26,-0.20),'b':(-0.79,-3.56,-0.19),'c':(-1.55,-4.67,-0.19),'d':(-0.83,-5.83,-0.19),'e':(0.58,-5.63,-0.19),'co':(3.13,0.40,-0.42),'ox':(-1.62,-7.00,-0.18)}
tetr=prepare(tetr,seed=47);coordsT=align_from_anchors(tetr,nT,target)
print('tetralin alignment error',[(i,round(float(np.linalg.norm(coordsT[nT[i]]-v)),2)) for i,v in target.items()]);
# With ring drawn in the image plane H points out and nitrogen points behind.
hidx=[x.GetIdx() for x in tetr.GetAtomWithIdx(nT['st']).GetNeighbors() if x.GetSymbol()=='H'][0]
print('stereochemistry H - N Z',coordsT[hidx,2]-coordsT[nT['n'],2]);
if coordsT[hidx,2]<coordsT[nT['n'],2]:
 tetr,nT=construct_tetralin(Chem.ChiralType.CHI_TETRAHEDRAL_CW);tetr=prepare(tetr,seed=47);coordsT=align_from_anchors(tetr,nT,target);print('stereo inverted new H-N Z',coordsT[hidx,2]-coordsT[nT['n'],2])
# full XYZ including explicitly embedded hydrogens
atoms=[('Rh',np.array([0.,0.,0.]))]
for m,xyz in [(inden,coordsI),(piv,coordsP),(tetr,coordsT)]:
 for a,r in zip(m.GetAtoms(),xyz):atoms.append((a.GetSymbol(),r))
def save(path,atoms):
 with open(path,'w') as f:
  f.write(str(len(atoms))+'\nRhodium indenyl pivalate tetralin carbamate cation (+1)\n')
  for a,r in atoms:f.write('%-2s %13.7f %13.7f %13.7f\n'%(a,*r))
save('initial.xyz',atoms)
